// Bounded receipt refresh only; never submits a new registration or requests OTPs.
function createReceiptPoll({refresh,isVisible,setTimer=setTimeout,clearTimer=clearTimeout,limit=72,delay=5000,slowAfter=12,slowDelay=30000}) {
  let pending=false,attempts=0,timer=null,stopped=false,final=false;
  const clear=()=>{if(timer!==null){clearTimer(timer);timer=null;}};
  function schedule(immediate=false) {
    clear();
    if (stopped || !pending || attempts>=limit || !isVisible()) return;
    timer=setTimer(()=>{timer=null;attempts++;void refresh();}, immediate ? 0 : final ? slowDelay : attempts<slowAfter ? delay : slowDelay);
  }
  return {
    before({manual=false}={}) { clear(); if(manual){attempts=0;stopped=false;} },
    after(status) { final=status==='complete';pending=['pending_sync','temporarily_unavailable','received_by_nova','complete'].includes(status); schedule(); },
    visibility() { schedule(true); },
    stop() { stopped=true;pending=false;clear(); },
    state:()=>({pending,attempts,exhausted:attempts>=limit,scheduled:timer!==null})
  };
}

